#include <stdio.h>
#include <string.h>

int main(int argc, char **argv)
{
    /* No strings supplied */
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    /* Too many strings (the original binary allowed at most 65 arguments,
       including the program name). */
    if (argc > 65) {
        puts("TOO_MANY");
        return 0;
    }

    /* Verify length of each argument (limit 1024 characters). */
    for (int i = 1; i < argc; ++i) {
        if (strlen(argv[i]) > 1024) {
            puts("TOO_LONG");
            return 0;
        }
    }

    /* Compute longest common prefix among all arguments. */
    size_t prefix_len = strlen(argv[1]);          /* start with first string */
    for (int i = 2; i < argc; ++i) {
        while (prefix_len > 0 &&
               strncmp(argv[1], argv[i], prefix_len) != 0) {
            --prefix_len;
        }
        if (prefix_len == 0)
            break;                               /* no common prefix any more */
    }

    /* Output the prefix (if any) followed by a newline. */
    if (prefix_len > 0) {
        fwrite(argv[1], 1, prefix_len, stdout);
    }
    putc('\n', stdout);
    return 0;
}
